import pandas as pd,numpy as np,json,pathlib
P=pathlib.Path('/tmp/edith/tools/nfl/qb_swap_current_season_20261113');W=pathlib.Path('/tmp/deep-research/brissett');v=json.load(open(W/'calculation.json'));s=pd.read_csv(P/'raw/sp2026.csv');fresh=pd.read_csv(W/'fresh_sp2026.csv',low_memory=False);games=pd.read_csv(P/'raw/games.csv');eligible=games[(games.season==2026)&(games.game_type=='REG')&(games.gameday<'2026-11-13')&games.home_score.notna()];keys={(int(r.week),t) for r in eligible.itertuples() for t in[r.home_team,r.away_team]}
s=s[(s.season_type=='REG')&s.apply(lambda r:(r.week,r.team) in keys,axis=1)];db=s.attempts.fillna(0)+s.sacks_suffered.fillna(0);s=s.assign(db=db);s=s[(s.db>0)&s.passing_epa.notna()];mu=s.passing_epa.sum()/s.db.sum();k=json.load(open(P/'out/eb_cs_params.json'))['2026'][0];groups=s.groupby('player_id').agg(epa=('passing_epa','sum'),db=('db','sum'));groups['Q']=(groups.epa+k*mu)/(groups.db+k);bal=s[s.team=='BAL'];emb=sum(r.db*groups.loc[r.player_id,'Q'] for r in bal.itertuples())/bal.db.sum();br=groups.loc[v['player_id']];assert abs(emb-v['embedded'])<1e-12;assert abs(br.Q-v['quality'])<1e-12
# Fresh feed preserves every original-cutoff passing row, not only Brissett.
fresh=fresh[(fresh.season_type=='REG')&fresh.apply(lambda r:(r.week,r.team) in keys,axis=1)];fresh=fresh.assign(db=fresh.attempts.fillna(0)+fresh.sacks_suffered.fillna(0));fresh=fresh[(fresh.db>0)&fresh.passing_epa.notna()]
cols=['player_id','week','team','db','passing_epa'];pd.testing.assert_frame_equal(s[cols].sort_values(cols[:3]).reset_index(drop=True),fresh[cols].sort_values(cols[:3]).reset_index(drop=True))
print('Independent aggregate reproduces EPA qualities; fresh passing data match all original cutoff rows.');print({'brissett_unshrunk_epa_per_db':float(br.epa/br.db),'league_mean':mu,'bal_embedded':emb,'brissett_quality':br.Q,'BALtotaldb':int(bal.db.sum())})
